#!/bin/sh
# Link already-built Icarus v13 objects into isolated browser modules.
# Inputs: build/icarus-src (or $ICARUS_SRC); outputs: build/wasm (or $WASM_OUT).
set -eu
out=${WASM_OUT:-/src/build/wasm}
live=/src/build/live
cd "${ICARUS_SRC:-build/icarus-src}"
export TMPDIR=/src/build/emscripten-tmp
mkdir -p "$out" "$live"
base='-sMODULARIZE=1 -sEXPORT_ES6=1 -sINVOKE_RUN=0 -sALLOW_MEMORY_GROWTH=1 -sFORCE_FILESYSTEM=1'
flags="$base -sEXPORTED_RUNTIME_METHODS=callMain,FS"
# Object names are generated by the upstream Makefiles and contain no whitespace.
emcc ivlpp/main.o ivlpp/lexor.o -o "$out/ivlpp.js" $flags
# The compiler links the vvp code generator and the schematic JSON writer
# (engine/tgt-json.cc, selected by flag DLL=json.tgt) statically.
em++ -std=c++11 -O2 -Wall -Wextra -I. -c /src/engine/tgt-json.cc -o "$live/tgt-json.o"
em++ ./*.o tgt-vvp/*.o "$live/tgt-json.o" vpi/v2005_math.o vpi/sys_clog2.o -o "$out/ivl.js" $flags
# Datapath Studio runtime extensions: memory capture + live session API (engine/vvp-live.cc).
em++ -std=c++11 -O2 -Wall -Wextra -I. -Ivvp -DHAVE_CONFIG_H -DICARUS_VPI_CONST=const \
  -c /src/engine/vvp-live.cc -o "$live/vvp-live.o"
set -- vvp/*.o "$live/vvp-live.o"
for object in vpi/*.o; do
  case "$object" in vpi/libvpi.o) ;; *) set -- "$@" "$object" ;; esac
done
em++ "$@" -o "$out/vvp.js" $base -sEXPORTED_RUNTIME_METHODS=callMain,FS,ccall \
  -sEXPORTED_FUNCTIONS=_main,_vvp_session_open,_vvp_session_set,_vvp_session_step,_vvp_session_close
